<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { RouterLink } from 'vue-router'; import { api, type Admission, type Patient } from '../services/api'
const route=useRoute(); const patient=ref<(Patient & {admissions:Admission[]})>(); const loading=ref(true); const error=ref('')
onMounted(async()=>{ try { patient.value=await api.patient(Number(route.params.patientId)) } catch(e){error.value=e instanceof Error?e.message:'Could not load patient'} finally{loading.value=false} })
</script>
<template><section v-if="patient"><div class="mb-7 flex items-center gap-2 text-sm text-[#8491a3]"><RouterLink to="/patients" class="hover:text-[#1c9f8d]">Patients</RouterLink><span class="material-symbols-rounded text-base">chevron_right</span><span class="font-semibold text-[#263650]">{{ patient.lastName }}, {{ patient.firstName }}</span></div><div class="mb-8 flex flex-col justify-between gap-5 rounded-2xl border border-[#e5ebf2] bg-white p-6 sm:flex-row sm:items-center"><div class="flex items-center gap-4"><div class="grid h-16 w-16 place-items-center rounded-2xl bg-[#d8f5ef] text-xl font-bold text-[#167e72]">{{ patient.firstName[0] }}{{ patient.lastName[0] }}</div><div><div class="mb-1 text-xs font-bold uppercase tracking-[.15em] text-[#1b9e8c]">Synthetic patient profile</div><h2 class="display text-2xl font-bold">{{ patient.lastName.toUpperCase() }}, {{ patient.firstName.toUpperCase() }}</h2><p class="mt-1 text-sm text-[#7b8799]">{{ patient.patientNumber }} · {{ patient.sex }} · Born {{ patient.dateOfBirth }}</p></div></div><div class="rounded-xl bg-[#f7f9fc] px-4 py-3 text-right"><div class="text-xs text-[#8996a8]">Patient ID</div><div class="font-bold">{{ patient.patientNumber }}</div></div></div><div class="mb-4 flex items-end justify-between"><div><h3 class="display text-xl font-bold">Admissions</h3><p class="mt-1 text-sm text-[#8491a3]">Documents are organized within each admission.</p></div><span class="rounded-full bg-[#edf8f6] px-3 py-1 text-xs font-bold text-[#198e7e]">{{ patient.admissions.length }} admissions</span></div><div class="grid gap-4 md:grid-cols-2"><RouterLink v-for="admission in patient.admissions" :key="admission.admissionId" :to="`/admissions/${admission.admissionId}`" class="group rounded-2xl border border-[#e5ebf2] bg-white p-5 transition hover:-translate-y-0.5 hover:border-[#7ed7c8] hover:shadow-lg hover:shadow-[#1c9f8d]/10"><div class="mb-5 flex items-start justify-between"><div class="flex items-center gap-3"><div class="grid h-11 w-11 place-items-center rounded-xl bg-[#eef3fa] text-[#6882a8]"><span class="material-symbols-rounded">local_hospital</span></div><div><div class="font-bold">{{ admission.admissionNumber }}</div><div class="mt-1 text-xs text-[#5d7592]">Encounter: {{ admission.encounterNumber }}</div><div class="mt-1 text-xs text-[#8996a8]">{{ admission.ward }}</div></div></div><span class="rounded-full px-3 py-1 text-[11px] font-bold" :class="admission.status === 'Active' ? 'bg-[#fff5d9] text-[#b88308]' : 'bg-[#edf8f6] text-[#198e7e]'">{{ admission.status }}</span></div><div class="grid grid-cols-2 gap-3 border-t border-[#edf1f5] pt-4 text-sm"><div><div class="text-xs text-[#94a1b2]">Admitted</div><div class="mt-1 font-semibold">{{ admission.admissionDate.slice(0,10) }}</div></div><div><div class="text-xs text-[#94a1b2]">Documents</div><div class="mt-1 font-semibold">{{ admission.documentCount }} files</div></div></div><div class="mt-5 flex items-center justify-end gap-1 text-xs font-bold text-[#1c9f8d]">View admission <span class="material-symbols-rounded text-base transition group-hover:translate-x-1">arrow_forward</span></div></RouterLink></div></section><div v-else-if="loading" class="p-12 text-center text-sm text-[#8496a8]">Loading patient record…</div><div v-else class="rounded-xl bg-red-50 p-5 text-red-700">{{ error }}</div></template>
